import {readFile,writeFile,appendFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const prefix='artifacts/hwpx-authority-20261007',observedAt=new Date().toISOString();
const final=await readFile(prefix+'-final.txt','utf8');
if(!/pass 50/u.test(final)||!/fail 0/u.test(final)||!/skipped 0/u.test(final))throw Error('final-test-gate-missing');
const report=`# HWPX 현재 권한·취소·부분 발행 결과\n\n관측: ${observedAt}\n\n이번 구현은 HWPX 생성 경로의 실제 권한·취소 및 생성 후 복구기록 실패를 수정한다. 전체 HWP/SQL 효과 인수를 완료한 의미가 아니다.\n\n## 재현과 수정\n\n- 변경 전 네 검사 모두 실패: 철회/취소되어도 생성, undo 저장 실패 후 이미 존재하는 결과 누락, 현재 권한 검사 없음. 원래 baseline 로그 보존.\n- 실행 전, Python 진입 직전, 생성 후, 실제 발행 직전과 완료 직전에 현재 private fence/취소를 검사한다. signed allowedPaths를 생성 전·발행 전 확인한다. 생성 staging SHA와 실제 발행 SHA를 대조한다.\n- Python에 동일 AbortSignal을 전달한다. Windows Python 생성 작업은 unnamed/non-inheritable JobObject에 자기 프로세스를 넣고 kill-on-close를 설정해 하위 프로세스까지 묶는다. Job 설정 실패는 예외이며 receipt guard 필수 계약이 맞지 않으면 발행하지 않는다.\n- 이미 발행했으면 undo/최종 권한 실패에서 failed·uncertain·outputPaths·changedItems를 보존한다. foreign target을 삭제하지 않는다. 렌더 파일의 undo 기록 실패도 실제 생성된 결과 경로를 보존한다.\n- 취소 직후 Windows 하위 프로세스가 핸들을 닫는 동안 owned staging 삭제만 제한 retry(10×100ms)를 적용한다. retry 소진 오류는 현재 삼키므로 모든 OS 잠금 조건에서 임시자료 정리 완료를 보장하지 않는다. 다음 부모 staging/영속 효과 작업의 남은 경계다.\n\n## 실제 검사와 실패 보존\n\n최종 50/50, 실패0·skip0. 실제 pinned Python/MCP HWPX 생성·생성후철회·목적지경합·취소 중 실제 staged document/Job 설정 관측 포함. 실제 Python 하위 프로세스가 생존하는 것을 확인하고 부모 종료 뒤 해당 하위 PID 종료도 관측했다. 기존 G는 실제 HWPX 내용을 재조회하며 기존 한컴 PDF/페이지/구조 fixture를 다시 검증했다. 이번에 새 한컴 COM 렌더는 실행하지 않았다.\n\n취소시험 최초 입력100블록은 정책40블록을 넘어서 사전차단되었다. 제품 제한을 완화하지 않고 fixture40으로 수정했으며 invalid-fixture 로그를 별도로 보존했다. 그 다음 실제 취소에서 staging이 남는 제품 결함을 발견했고 inflight-failed/before-job 로그를 보존했다. 단순 부모 종료는 MCP 하위 프로세스 종료를 보장하지 않아 JobObject로 수정했다. 고정된 최종 오라클(실제 진행 중 취소·최종출력0·owned stage0)은 바꾸지 않았다.\n\n독립13/13(실패0·skip0): 실제 파일/B packet/fence/Core authority 검사는 원본, Python 생성만 hook으로 대체했다. Job receipt 누락/false 및 현재권한/경합/부분발행을 검사한다. hook guard 값이 실제 OS 보호를 증명하지 않으며 실제 Job 검사는 root 증거로 분리한다. 독립검사 초기 fixture hook 작성 오류도 별도 로그로 남겼다.\n\n빌드와 Core 계약 검사 exit0. 연결 범위 런타임 ready 확인. 서비스 재시작/설치EXE 활성화0·외부발송/유료API0·실계정변경0. 테스트는 합성 자료와 격리 임시 폴더 사용. 비용은 미측정.\n\n## 인수와 다음 작업\n\n공식60/100 유지. 현재 활성 Core worker는 hwp.create를 A_CORE_AUTHORITY_EXECUTOR_FENCE_UNSUPPORTED로 차단하며 adapter 호출0(독립 실제 관측)이다. HWP native authoring의 parent staging/Job guard, 모든 렌더 파일 manifest, Core SQL effect/private artifact contract, B claim/receipt 재시작 복원, G 원래 문서·현재 파일 대사가 남았다. worker allowlist만 늘려 차단을 해제하지 않는다. 원래 전체100개의 항목을 유지한다.\n\n공식 근거: [Microsoft Job Objects](https://learn.microsoft.com/en-us/windows/win32/procthread/job-objects), [AssignProcessToJobObject](https://learn.microsoft.com/en-us/windows/win32/api/jobapi2/nf-jobapi2-assignprocesstojobobject).\n`;
await writeFile(prefix+'-report.md',report,{flag:'wx'});
const paths=['apps/pc-agent/src/pc-agent-runtime.js','apps/pc-agent/src/adapters/hwpx/hwpx-mcp-create.py','apps/pc-agent/src/adapters/hwpx/process-job-guard.py','tests/hwpx-authority-boundary.test.js','tests/hwpx-process-job.test.js'];
await writeFile(prefix+'-source.json',JSON.stringify(await Promise.all(paths.map(async path=>({path,sha256:createHash('sha256').update(await readFile(path)).digest('hex')}))),null,2),{flag:'wx'});
await writeFile(prefix+'-attempt.json',JSON.stringify({id:'hwpx-authority-20261007',candidateId:'agent-platform-observed-scenario-status',kind:'workflow-test',reportedOutcome:'passed',observedAt,hypothesis:'생성 프로세스를 OS 소유 경계로 묶고 현재 권한과 취소를 발행 경계에서 검사하면 취소 후 발행과 부분 결과의 증거 소실을 방지할 수 있다.',lesson:'Python 부모 종료만으로 MCP 자식 종료가 보장되지 않았다. JobObject와 실제 중단 관측이 필요하다. 생성 후 undo 실패는 출력0이 아닌 uncertain으로 보존한다.',limitations:'최종50+독립13. 실제 HWPX/Job 취소·독립hook/B/Core차단 구분. 전체HWP native/SQL effect/recovery·운영EXE·모든OS락 cleanup 미완료. 공식60/100·비용미측정.',evidencePaths:[prefix+'-report.md',prefix+'-source.json',prefix+'-final.txt',prefix+'-build.txt',prefix+'-contract.txt',prefix+'-baseline.txt',prefix+'-invalid-fixture.txt',prefix+'-inflight-failed.txt',prefix+'-job-tree.txt',prefix+'-cancel-job.txt',prefix+'-independent.md',prefix+'-independent.json',prefix+'-independent.txt',prefix+'-independent.test.mjs',prefix+'-runtime.json']},null,2),{flag:'wx'});
await appendFile('docs/execution-to-100.md',`\n최신 ${prefix}-report.md: HWPX 현재권한/취소/signed범위/부분발행 uncertain·실제MCP inflight+Python Job 하위종료·50/50/독립13/build/contract. Core HWP fence 미지원 안전차단 실측. 공식60·운영EXE활성화0. 다음 HWP/HWPX 전체manifest/parent staging/SQL 효과·영속claim/G 복구.\n`);
